import{z as i,x as s,o as e,c as m,q as t,j as r,D as E,d as B,s as n,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"数值健康检查","description":"","frontmatter":{"title":"数值健康检查","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-numerical-health.md","filePath":"llm/ti-numerical-health.md","lastUpdated":1791063341000}'),p={name:"llm/ti-numerical-health.md"};function d(h,a,D,f,C,c){const l=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=t('<h1 id="数值健康检查" tabindex="-1">数值健康检查 <a class="header-anchor" href="#数值健康检查" aria-label="Permalink to &quot;数值健康检查&quot;">​</a></h1><div class="epigraph"><p>健康检查的本质是把「希望有人盯着」改写成机器可执行的断言，让人不做第一发现者。</p><footer>—— 据 FP8/FP16 混合精度训练与大规模训练健康监控实践整理</footer></div><p><a href="/llm/ti-gradient-weight-histograms">上一课</a>把分布形状接进观测面，而形状漂移常是数值病的皮肤。数值的<strong>监控内容</strong>——溢出计数、amax 水位、尺度抖动、零更新层——<a href="/llm/num-longrun-health">长期训练的健康监控</a>已经列成仪表盘；精度格式的边界在<a href="/llm/num-float-formats">浮点格式谱系</a>，混合精度方案在<a href="/llm/pretrain-mixed-precision">混合精度 BF16 / FP8 训练</a>。本课写观测之上的执行层：把数值健康做成<strong>自动检查</strong>，让异常触发动作而不是通知。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>仪表盘有个结构性缺陷：它默认有人看，而长跑以周计、注意力以分钟计；损失可见时能做的只剩回滚。检查要补的是三个时间点的自动化。<strong>启动时</strong>：初始化统计是否在预期区间、假批能否一步过拟合、梯度能否到达所有层——这些在 step 0 就该挡住作业，而不是三天后由曲线回答。<strong>每步中</strong>：出现 NaN 与 Inf 时，只报「损失变 NaN」等于没有信息，作业继续跑出几千步废数据。<strong>越线后</strong>：人不在时绊网先动——跳批、冻结学习率、回退检查点——而所有自动动作都要留痕，否则复盘分不清「系统自愈」与「带病续跑」。</p><p><span class="marginnote">数字实例：fp16 能表示的最大数约 65504，某个 logit 涨到十万，一步之内就变成 Inf；Inf 减 Inf 得 NaN，而 NaN 会顺着梯度传遍全网——所以定位必须找「首个非有限值」，等损失整体变 NaN 再查，每一层都已是 NaN，什么也查不出来。</span></p><h3 id="三层检查的分工" tabindex="-1">三层检查的分工 <a class="header-anchor" href="#三层检查的分工" aria-label="Permalink to &quot;三层检查的分工&quot;">​</a></h3><p>启动自检是一次性门禁：初始化统计、单步前反向的非有限值扫描、十步过拟合小样本。内联绊网是廉价常开的断言：损失与 logit 的量级带、溢出与跳步计数率、梯度范数贴顶时长，超带即触发分级响应。诊断复现是昂贵非常开的：首个非有限值的逐层定位靠挂前向钩子逐层检查，框架的完整 anomaly 模式让每步慢数倍，只在回放调试时打开。三层共享同一条纪律：<strong>断言失败必须带定位</strong>（哪层、哪个张量、第几步），不带定位的告警会被养成忽略习惯。</p><p><span class="marginnote">术语翻译：断言（assertion）就是写进程序的一句「此处必须成立，否则立刻报错」，比如「损失必须有限」「梯度范数不得超过一亿」。它与「希望有人盯着仪表盘」的区别在于：断言由机器在当步执行，人从第一发现者的位置上退了下来。</span></p><p><span class="marginnote">fp16 的表示上限约 65504，一次未裁剪的激活爆炸足以把整场训练打成 NaN；而定位首个 NaN 的钩子链只在调试时全开——健康检查的预算同钩子纪律一样按全程折算，常开的必须是廉价断言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地按四步。其一，把断言写进作业配置而不是脚本里：量级带、计数率阈值、响应动作，随训练配方走版本评审，与 \\(\\beta_2\\) 尖峰模式（<a href="/llm/adam-beta2-spikes">Adam β₂ 与损失尖峰</a>）等已知病症对应。其二，绊网分级：一级只记录，二级跳批或冻结日程，三级回退到最近 complete 检查点并通知；升级路径写死，禁止现场改阈值。其三，稳定器当配置管：<a href="/llm/z-loss">z-loss</a> 压 logit 漂移、<a href="/llm/qk-norm-pretrain">QK-Norm</a> 压注意力 logits，开与关都记录在案——稳定器掩盖的病症仍要靠断言兜底。其四，演练：注入一次 NaN 与一次尖峰，验证绊网真的触发、定位、回退——没演练过的绊网与没恢复过的检查点同样不可信。</p>',12)),(e(),r(o,null,{default:E(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E5%90%AF%E5%8A%A8%E8%87%AA%E6%A3%80%3A%20%E5%88%9D%E5%A7%8B%E5%8C%96%2F%E5%8D%95%E6%AD%A5%E8%BF%87%E6%8B%9F%E5%90%88%2F%E6%A2%AF%E5%BA%A6%E5%88%B0%E8%BE%BE%22%5D%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20BLOCK%5B%22%E6%8B%92%E8%B7%91%3A%20%E4%BF%AE%E9%85%8D%E7%BD%AE%22%5D%0A%20%20PRE%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20RUN%5B%22%E8%AE%AD%E7%BB%83%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20RUN%20--%3E%20W%7B%22%E5%86%85%E8%81%94%E7%BB%8A%E7%BD%91%3A%20%E9%87%8F%E7%BA%A7%E5%B8%A6%2F%E6%BA%A2%E5%87%BA%E7%8E%87%2F%E8%B4%B4%E9%A1%B6%E6%97%B6%E9%95%BF%22%7D%0A%20%20W%20--%3E%7C%E4%B8%80%E7%BA%A7%7C%20LOG%5B%22%E8%AE%B0%E5%BD%95%E5%B9%B6%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20W%20--%3E%7C%E4%BA%8C%E7%BA%A7%7C%20ACT%5B%22%E8%B7%B3%E6%89%B9%E6%88%96%E5%86%BB%E7%BB%93%E5%AD%A6%E4%B9%A0%E7%8E%87%22%5D%0A%20%20W%20--%3E%7C%E4%B8%89%E7%BA%A7%7C%20RB%5B%22%E5%9B%9E%E9%80%80%E6%9C%80%E8%BF%91%20complete%20%2B%20%E9%80%9A%E7%9F%A5%22%5D%0A%20%20W%20--%3E%7C%E5%AE%9A%E4%BD%8D%E5%A4%B1%E8%B4%A5%7C%20DBG%5B%22%E6%8C%82%E9%92%A9%E5%AD%90%E5%A4%8D%E7%8E%B0%2C%20%E9%80%90%E5%B1%82%E6%89%BE%E9%A6%96%E4%B8%AA%E9%9D%9E%E6%9C%89%E9%99%90%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"断言优于盯盘的机理是延迟差：绊网在异常当步读到信号，仪表盘要等人看到再行动，中间隔小时级；对每秒都在恶化的 NaN 传播，小时级等于全损。分级响应的机理与熔断相同：一级收集证据、二级止损、三级恢复，级别与置信度对应，避免任何单一阈值既当报警又当开关。留痕的机理是归因闭环——自动动作改写了轨迹（跳过的批、回退的点），不留痕则下游所有对比分析的地基被悄悄抽掉。",-1)),(e(),r(o,null,{default:E(()=>[n(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E7%AC%AC%200%20%E6%AD%A5%3A%20%E6%9F%90%E5%B1%82%E5%87%BA%E7%8E%B0%E9%A6%96%E4%B8%AA%20Inf%22%5D%20--%3E%20T1%5B%22%E6%95%B0%E6%AD%A5%E5%86%85%3A%20NaN%20%E6%B1%A1%E6%9F%93%E6%A2%AF%E5%BA%A6%E4%B8%8E%E6%9D%83%E9%87%8D%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E6%95%B0%E5%8D%81%E6%AD%A5%E5%86%85%3A%20%E6%8D%9F%E5%A4%B1%E6%95%B4%E4%BD%93%E5%8F%98%20NaN%22%5D%0A%20%20T0%20-.-%3E%7C%22%E5%86%85%E8%81%94%E7%BB%8A%E7%BD%91%3A%20%E5%BD%93%E6%AD%A5%E8%A7%A6%E5%8F%91%22%7C%20ACT%5B%22%E8%B7%B3%E6%89%B9%E6%88%96%E5%9B%9E%E9%80%80%2C%20%E5%8F%AA%E6%8D%9F%E5%A4%B1%E4%B8%80%E6%89%B9%22%5D%0A%20%20T2%20-.-%3E%7C%22%E4%BA%BA%E7%9C%8B%E4%BB%AA%E8%A1%A8%E7%9B%98%3A%20%E5%B0%8F%E6%97%B6%E7%BA%A7%E5%BB%B6%E8%BF%9F%22%7C%20LOSE%5B%22%E6%95%B0%E5%8D%83%E6%AD%A5%E5%BA%9F%E6%95%B0%E6%8D%AE%2C%20%E5%8F%AA%E8%83%BD%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>演练的机理沿用检查点课的结论：恢复路径的价值只在执行时兑现，而断言代码是最常被「顺手优化掉」的路径，注入式演练是唯一能证明它还活着的手段。</p><p><span class="marginnote">常见误区：初学者容易把绊网阈值设得极敏感，「宁可误报不可漏报」——实际上持续误报的结局是全员养成忽略习惯，甚至干脆关掉绊网，比没有绊网更危险。正确姿势是从宽起步，每出一次真实事故，就用它的数据回推收紧一次阈值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管数值与过程健康的自动检查，不管数值方案怎么选：精度配比、缩放策略、稳定器取舍归低精度各课；损失曲线怎么读归上一课；「健康但错误」的静默错位要靠数据指纹与回放，不在断言能力内。断言过密也有成本：误报的结局是全员关闭绊网，阈值宁可从宽起步、按事故回推收紧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层分工：启动自检挡低级错误，内联绊网常开廉价断言，昂贵诊断只在复现时全开。</li><li>断言失败必须带定位：哪层、哪个张量、第几步。</li><li>绊网分级响应，升级路径写死，所有自动动作留痕进日志。</li><li>稳定器与断言并用，注入式演练证明绊网活着。</li><li>出处：据 FP16/FP8 混合精度训练（Micikevicius et al., 2022 一线格式报告）与大规模训练监控实践整理；监控面清单见<a href="/llm/num-longrun-health">长期训练的健康监控</a>。</li></ul>',6))])}const N=i(p,[["render",d]]);export{F as __pageData,N as default};
